/**
 * The generated lists of server test files that may run in the parallel `unit`
 * Vitest project. Everything not listed runs in the serial `integration`
 * project, so new or unprobed test files are serial by default.
 *
 * Never edit the lists by hand: regenerate them with
 * `bun run --cwd apps/server test:groups [paths...]` (see `updateServerTestGroups.ts`).
 * They are split per top-level area (`src/provider`, `scripts`, ...) and chunked
 * so every generated file stays within the repository's 400-line limit.
 */
import * as FS from "node:fs";
import * as Path from "node:path";

export const MANIFEST_DIR = "vitest.unit-files";
const MAX_ENTRIES_PER_FILE = 390;

const HEADER = [
  "# Generated by apps/server/scripts/updateServerTestGroups.ts. Do not edit by hand.",
  "# Server test files that run in the parallel `unit` Vitest project: they passed",
  "# probe runs without touching processes, PTYs, workers, SQLite, sockets, fetch, or",
  "# filesystem paths outside their own mkdtemp directories. Unlisted files run serially.",
];

/** `integration/` holds end-to-end orchestration suites; they always run serially. */
export const isParallelCandidate = (file: string) => !file.startsWith("integration/");

const manifestDir = (serverRoot: string) => Path.join(serverRoot, MANIFEST_DIR);

const listManifestFiles = (serverRoot: string) => {
  try {
    return FS.readdirSync(manifestDir(serverRoot)).filter((name) => name.endsWith(".txt"));
  } catch {
    return [];
  }
};

export function readParallelTestFiles(serverRoot: string): string[] {
  const files: string[] = [];
  for (const name of listManifestFiles(serverRoot)) {
    const text = FS.readFileSync(Path.join(manifestDir(serverRoot), name), "utf8");
    for (const raw of text.split("\n")) {
      const line = raw.trim();
      if (line.length === 0 || line.startsWith("#") || !isParallelCandidate(line)) continue;
      if (FS.existsSync(Path.join(serverRoot, line))) files.push(line);
    }
  }
  return files.toSorted();
}

/** `src/provider/Layers/Foo.test.ts` -> `src.provider`; `scripts/x.test.ts` -> `scripts`. */
const areaOf = (file: string) => {
  const segments = file.split("/");
  return segments.slice(0, Math.min(2, segments.length - 1)).join(".");
};

export function writeParallelTestFiles(serverRoot: string, files: Iterable<string>): void {
  const byArea = new Map<string, string[]>();
  for (const file of [...new Set(files)].toSorted()) {
    const area = areaOf(file);
    byArea.set(area, [...(byArea.get(area) ?? []), file]);
  }
  FS.mkdirSync(manifestDir(serverRoot), { recursive: true });
  for (const name of listManifestFiles(serverRoot)) {
    FS.rmSync(Path.join(manifestDir(serverRoot), name));
  }
  for (const [area, entries] of byArea) {
    for (let start = 0; start < entries.length; start += MAX_ENTRIES_PER_FILE) {
      const chunk = start / MAX_ENTRIES_PER_FILE;
      const name = chunk === 0 ? `${area}.txt` : `${area}.${chunk + 1}.txt`;
      const body = [...HEADER, ...entries.slice(start, start + MAX_ENTRIES_PER_FILE)];
      FS.writeFileSync(Path.join(manifestDir(serverRoot), name), `${body.join("\n")}\n`);
    }
  }
}

/** Escape glob metacharacters so a listed path only ever matches itself. */
export const escapeGlob = (file: string) => file.replace(/[()[\]{}*?!+@]/g, "\\$&");
